// Security → Assignments tab (console/pane ↔ profile), AS GRAPH SOURCE (#3646, epic #3604). Transcribed from the live feature file: the runtime
// loader compiles this and mounts it, resolving every import to the app's real modules (the shared/ui
// design system + the store via appModules, the security lib surface via the security graph-platform,
// and the sibling tab bodies as @/components/* graph records). Behaviour runs here — no forked render path.
// Security — Assignments tab (#1643 split from SecurityWorkspace).
//
// The always-present application sessions + the per-pane console assignments, each
// pane showing its resolved command allowlist (guaranteed ∪ profile ∪ project ∪
// repo). The pane-profile picker (#681) is the click-to-open `ProfileSelect`.
// Preview note: the agentProfiles/appSession/badgeTone libs and `CardListRow` (a `@/shared/ui/data`
// path with no matching kit primitive) are app-internal/unresolvable in this sandbox — inlined locally
// below, with sample defaults so this tab previews standalone.

import { useEffect, useState } from "react";
import { Chip } from "@/shared/ui/data/Chip";
import { SectionHeader } from "@/shared/ui/layout/SectionHeader";
import { Button } from "@/shared/ui/controls/Button";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";

interface AgentProfile { id: string; name: string; color: string; mode: "deny" | "ask" | "allow"; commands: string[]; session?: string; surface?: string }
interface Pane { id: string; agent: string; status: "running" | "idle" | "blocked"; profileId: string }
interface ConsoleSession { id: string; name: string; repo: string; panes: Pane[]; projectAllow?: string[]; repoAllow?: string[] }

const GUARANTEED = ["gh", "git"];
function resolveAllowlistFrom(c: ConsoleSession, p?: AgentProfile): { cmd: string; origin: "guaranteed" | "profile" | "project" | "repo" }[] {
  const out: { cmd: string; origin: "guaranteed" | "profile" | "project" | "repo" }[] = GUARANTEED.map((cmd) => ({ cmd, origin: "guaranteed" as const }));
  if (p) out.push(...p.commands.map((cmd) => ({ cmd, origin: "profile" as const })));
  for (const cmd of c.projectAllow ?? []) out.push({ cmd, origin: "project" });
  for (const cmd of c.repoAllow ?? []) out.push({ cmd, origin: "repo" });
  return out;
}
function appSessionTag(p: AgentProfile): string { return p.name; }
function modeTone(m: "deny" | "ask" | "allow"): "danger" | "accent" | "success" { return m === "deny" ? "danger" : m === "ask" ? "accent" : "success"; }

const SAMPLE_ROLES: AgentProfile[] = [
  { id: "sys_planner", name: "Planner", color: "oklch(0.72 0.12 175)", mode: "allow", commands: ["npm", "cargo"], session: "planner", surface: "planning board" },
];
const SAMPLE_PROFILES: AgentProfile[] = [
  { id: "pf_sandbox", name: "Sandbox", color: "oklch(0.78 0.14 70)", mode: "ask", commands: ["cargo", "npm"] },
  { id: "pf_reviewer", name: "Reviewer", color: "oklch(0.68 0.18 25)", mode: "ask", commands: ["git"] },
];
const SAMPLE_CONSOLES: ConsoleSession[] = [
  { id: "c1", name: "design-studio", repo: "design-studio", projectAllow: ["build", "test"], panes: [
    { id: "t0p1", agent: "worker-1", status: "running", profileId: "pf_sandbox" },
    { id: "t0p2", agent: "worker-2", status: "blocked", profileId: "pf_reviewer" },
  ] },
  { id: "c2", name: "infra", repo: "infra", panes: [
    { id: "t1p1", agent: "worker-3", status: "idle", profileId: "pf_sandbox" },
  ] },
];
function sampleFind(id: string): AgentProfile | undefined {
  return [...SAMPLE_ROLES, ...SAMPLE_PROFILES].find((p) => p.id === id);
}

/** A row card matching the shared `@/shared/ui/data/CardListRow` visual shape — inlined locally since
 *  base-studio-code has no matching kit primitive for it yet. */
function CardListRow({ lead, title, titleAside, subtitle, body, trailing, accent, selected, onClick }: {
  lead?: React.ReactNode; title: React.ReactNode; titleAside?: React.ReactNode; subtitle?: React.ReactNode;
  body?: React.ReactNode; trailing?: React.ReactNode; accent?: string; selected?: boolean; onClick?: () => void;
}) {
  return (
    <Box onClick={onClick} style={{
      display: "flex", flexDirection: "column", gap: 8, padding: "10px 12px", borderRadius: 7, marginBottom: 6,
      cursor: onClick ? "pointer" : undefined,
      background: selected ? "var(--bg-elev2)" : "var(--bg-elev)",
      borderLeft: accent ? `2px solid ${accent}` : "2px solid transparent",
      border: selected ? "1px solid var(--accent)" : "1px solid var(--border-soft)",
    }}>
      <Row align="center" gap={8} wrap>
        {lead}
        <Box style={{ flex: 1, minWidth: 0 }}>
          <Row align="baseline" gap={8} wrap>
            <Text as="span" weight={600} style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{title}</Text>
            {titleAside}
          </Row>
          {subtitle && <Box style={{ marginTop: 2 }}>{subtitle}</Box>}
        </Box>
        {trailing}
      </Row>
      {body}
    </Box>
  );
}

export interface AssignmentsTabProps {
  roles?: AgentProfile[]; consoles?: ConsoleSession[]; paneTotal?: number;
  profiles?: AgentProfile[];
  onAssign?: (consoleId: string, paneId: string, profileId: string) => void;
  onOpen?: (id: string) => void;
  find?: (id: string) => AgentProfile | undefined;
}

/** A click-to-open dropdown for picking a pane's profile (#681). */
export function ProfileSelect({ current, profiles, onPick }: {
  current?: AgentProfile; profiles: AgentProfile[]; onPick: (id: string) => void;
}) {
  const [open, setOpen] = useState(false);
  useEffect(() => {
    if (!open) return;
    const close = () => setOpen(false);
    window.addEventListener("click", close);
    return () => window.removeEventListener("click", close);
  }, [open]);
  return (
    <Box style={{ position: "relative", display: "inline-flex", alignItems: "center", gap: 6, cursor: "pointer" }} onClick={(e) => { e.stopPropagation(); setOpen((o) => !o); }}>
      <Box as="span" bg={current?.color} radius={99} style={{ width: 9, height: 9 }} />
      <Text as="span" mono size={11}>{current?.name ?? "—"}</Text>
      {current && <Chip tone={modeTone(current.mode)} size="sm" style={{ marginLeft: 2 }}>{current.mode}</Chip>}
      <Text as="span" tone="dim" size={10}>▾</Text>
      {open && (
        <Box style={{ position: "absolute", top: "100%", right: 0, marginTop: 4, zIndex: 20, background: "var(--bg-elev2)", border: "1px solid var(--border-soft)", borderRadius: 7, padding: 4, minWidth: 160, boxShadow: "0 8px 24px rgba(0,0,0,.4)" }} role="listbox" onClick={(e) => e.stopPropagation()}>
          {profiles.map((p) => (
            <button
              key={p.id}
              type="button"
              role="option"
              aria-selected={p.id === current?.id}
              onClick={() => { onPick(p.id); setOpen(false); }}
              style={{
                display: "flex", alignItems: "center", gap: 8, width: "100%", padding: "6px 8px", borderRadius: 5, border: 0,
                background: p.id === current?.id ? "var(--bg-elev)" : "transparent", cursor: "pointer", font: "inherit", textAlign: "left",
              }}
            >
              <Box as="span" bg={p.color} radius={99} style={{ width: 8, height: 8 }} />
              <Text as="span" size={11} style={{ flex: 1 }}>{p.name}</Text>
              <Chip tone={modeTone(p.mode)} size="sm">{p.mode}</Chip>
            </button>
          ))}
        </Box>
      )}
    </Box>
  );
}

function AppSessionRow({ p, onOpen }: { p: AgentProfile; onOpen: (id: string) => void }) {
  const all = [
    ...GUARANTEED.map((c) => ({ cmd: c, origin: "guaranteed" as const })),
    ...p.commands.map((c) => ({ cmd: c, origin: "profile" as const })),
  ];
  return (
    <CardListRow
      lead={<Box as="span" bg="var(--success)" radius={99} style={{ width: 8, height: 8 }} />}
      title={appSessionTag(p)}
      subtitle={<Text as="span" mono size={10.5} tone="dim">{p.session}</Text>}
      titleAside={
        <Box onClick={() => onOpen(p.id)} style={{ display: "inline-flex", alignItems: "center", gap: 6, cursor: "pointer" }}>
          <Box as="span" bg={p.color} radius={99} style={{ width: 8, height: 8 }} />
          <Text as="span" size={11}>{p.name}</Text>
          <Chip tone="info" size="xs" style={{ marginLeft: 2 }}>locked</Chip>
        </Box>
      }
      body={
        <Row gap={6} wrap align="stretch">
          <Text as="span" mono size={10} tone="dim">runs:</Text>
          {all.map((r) => (
            <Box as="span" key={r.cmd} className="mono" style={{ fontSize: 10.5, padding: "2px 8px", borderRadius: 999, border: r.origin === "guaranteed" ? "1px solid var(--info)" : "1px solid var(--border-soft)", color: r.origin === "guaranteed" ? "var(--info)" : "var(--fg-muted)" }}>{r.cmd}</Box>
          ))}
          <Box as="span" className="mono" style={{ fontSize: 10.5, padding: "2px 8px", borderRadius: 999, border: "1px dashed var(--border-soft)", color: "var(--fg-dim)" }}>owns {p.surface}</Box>
        </Row>
      }
      trailing={<Button variant="ghost" style={{ height: 24, fontSize: 10 }} onClick={() => onOpen(p.id)}>edit role →</Button>}
    />
  );
}

export function AssignmentsTab({
  roles = SAMPLE_ROLES, consoles = SAMPLE_CONSOLES, paneTotal = SAMPLE_CONSOLES.reduce((a, c) => a + c.panes.length, 0),
  profiles = SAMPLE_PROFILES, onAssign = () => {}, onOpen = () => {}, find = sampleFind,
}: AssignmentsTabProps) {
  return (
    <Box style={{ display: "flex", flexDirection: "column", width: "100%" }}>
      <SectionHeader title="Application sessions" hint="always present · role fixed" meta={<>{roles.length} system roles</>} />
      <Box style={{ marginBottom: 14 }}>
        <Box style={{ border: "1px solid color-mix(in oklch, var(--info), transparent 78%)", borderRadius: 8, overflow: "hidden" }}>
          <Row align="center" gap={8} wrap style={{ padding: "8px 12px", background: "color-mix(in oklch, var(--info), transparent 92%)" }}>
            <Box as="span" bg="var(--info)" radius={99} style={{ width: 8, height: 8 }} />
            <Text as="span" weight={600} size={11.5}>system</Text>
            <Text as="span" mono size={10} tone="dim">workspace-wide</Text>
            <Box style={{ flex: 1 }} />
            <Text as="span" mono size={10} tone="dim">not reassignable</Text>
          </Row>
          <Box style={{ padding: 10 }}>
            {roles.map((p) => <AppSessionRow key={p.id} p={p} onOpen={onOpen} />)}
          </Box>
        </Box>
      </Box>

      <SectionHeader title="Console sessions" hint="one profile per pane" meta={<>{consoles.length} consoles · {paneTotal} panes</>} />
      <Box style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {consoles.map((c) => (
          <Box key={c.id} style={{ border: "1px solid var(--border-soft)", borderRadius: 8, overflow: "hidden" }}>
            <Row align="center" gap={8} wrap style={{ padding: "8px 12px", background: "var(--bg-elev2)" }}>
              <Box as="span" bg="var(--fg-dim)" radius={99} style={{ width: 8, height: 8 }} />
              <Text as="span" weight={600} size={11.5}>{c.name}</Text>
              <Text as="span" mono size={10} tone="dim">{c.repo}</Text>
              <Box style={{ flex: 1 }} />
              <Text as="span" mono size={10} tone="dim" style={{ whiteSpace: "nowrap" }}>
                allow: {(c.projectAllow || []).join(", ") || "—"}{c.repoAllow ? ` · repo: ${c.repoAllow.join(", ")}` : ""}
              </Text>
            </Row>
            <Box style={{ padding: 10 }}>
              {c.panes.map((pane) => {
                const p = find(pane.profileId);
                const resolved = resolveAllowlistFrom(c, p);
                return (
                  <CardListRow
                    key={pane.id}
                    lead={<Box as="span" bg={pane.status === "running" ? "var(--success)" : pane.status === "blocked" ? "var(--danger)" : "var(--fg-dim)"} radius={99} style={{ width: 8, height: 8 }} />}
                    title={pane.agent}
                    subtitle={<Text as="span" mono size={10.5} tone="dim">{pane.id}</Text>}
                    titleAside={<ProfileSelect current={p} profiles={profiles} onPick={(id) => onAssign(c.id, pane.id, id)} />}
                    body={
                      <Row gap={6} wrap align="stretch">
                        <Text as="span" mono size={10} tone="dim">runs:</Text>
                        {resolved.map((r) => (
                          <Box as="span" key={r.cmd} className="mono" style={{ fontSize: 10.5, padding: "2px 8px", borderRadius: 999, border: r.origin === "guaranteed" ? "1px solid var(--info)" : "1px solid var(--border-soft)", color: r.origin === "guaranteed" ? "var(--info)" : "var(--fg-muted)" }}>{r.cmd}</Box>
                        ))}
                        {resolved.length === 0 && <Box as="span" className="mono" style={{ fontSize: 10.5, padding: "2px 8px", borderRadius: 999, border: "1px dashed var(--border-soft)", color: "var(--fg-dim)" }}>— prompt for everything —</Box>}
                      </Row>
                    }
                    trailing={<Button variant="ghost" style={{ height: 24, fontSize: 10 }} onClick={() => onOpen(pane.profileId)}>edit profile →</Button>}
                  />
                );
              })}
            </Box>
          </Box>
        ))}
      </Box>
    </Box>
  );
}

